// init fills cisco.optics.esnr metric with initial data.
func (m *metricCiscoOpticsEsnr) init() {
	m.data.SetName("cisco.optics.esnr")
	m.data.SetDescription("Effective signal-to-noise ratio reported by an allowlisted device VDM sensor")
	m.data.SetUnit("dB")
	m.data.SetEmptyGauge()
	m.data.Gauge().DataPoints().EnsureCapacity(m.capacity)
	m.aggDataPoints = m.aggDataPoints[:0]
}

func (m *metricCiscoOpticsEsnr) recordDataPoint(start pcommon.Timestamp, ts pcommon.Timestamp, val float64, networkInterfaceNameAttributeValue string, ciscoOpticsLaneAttributeValue string, ciscoOpticsSensorAttributeValue string, ciscoOpticsProfileAttributeValue string, ciscoOpticsExperimentalAttributeValue bool) {
	if !m.config.Enabled {
		return
	}

	dp := pmetric.NewNumberDataPoint()
	dp.SetStartTimestamp(start)
	dp.SetTimestamp(ts)
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsEsnrMetricAttributeKeyNetworkInterfaceName) {
		dp.Attributes().PutStr("network.interface.name", networkInterfaceNameAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsEsnrMetricAttributeKeyCiscoOpticsLane) {
		dp.Attributes().PutStr("cisco.optics.lane", ciscoOpticsLaneAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsEsnrMetricAttributeKeyCiscoOpticsSensor) {
		dp.Attributes().PutStr("cisco.optics.sensor", ciscoOpticsSensorAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsEsnrMetricAttributeKeyCiscoOpticsProfile) {
		dp.Attributes().PutStr("cisco.optics.profile", ciscoOpticsProfileAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsEsnrMetricAttributeKeyCiscoOpticsExperimental) {
		dp.Attributes().PutBool("cisco.optics.experimental", ciscoOpticsExperimentalAttributeValue)
	}

	var s string
	dps := m.data.Gauge().DataPoints()
	for i := 0; i < dps.Len(); i++ {
		dpi := dps.At(i)
		if dp.Attributes().Equal(dpi.Attributes()) && dp.StartTimestamp() == dpi.StartTimestamp() && dp.Timestamp() == dpi.Timestamp() {
			switch s = m.config.AggregationStrategy; s {
			case AggregationStrategySum, AggregationStrategyAvg:
				dpi.SetDoubleValue(dpi.DoubleValue() + val)
				m.aggDataPoints[i] += 1
				return
			case AggregationStrategyMin:
				if dpi.DoubleValue() > val {
					dpi.SetDoubleValue(val)
				}
				return
			case AggregationStrategyMax:
				if dpi.DoubleValue() < val {
					dpi.SetDoubleValue(val)
				}
				return
			}
		}
	}

	dp.SetDoubleValue(val)
	m.aggDataPoints = append(m.aggDataPoints, 1)
	dp.MoveTo(dps.AppendEmpty())
}

// updateCapacity saves max length of data point slices that will be used for the slice capacity.
func (m *metricCiscoOpticsEsnr) updateCapacity() {
	if m.data.Gauge().DataPoints().Len() > m.capacity {
		m.capacity = m.data.Gauge().DataPoints().Len()
	}
}

// emit appends recorded metric data to a metrics slice and prepares it for recording another set of data points.
func (m *metricCiscoOpticsEsnr) emit(metrics pmetric.MetricSlice) {
	if m.config.Enabled && m.data.Gauge().DataPoints().Len() > 0 {
		if m.config.AggregationStrategy == AggregationStrategyAvg {
			for i, aggCount := range m.aggDataPoints {
				m.data.Gauge().DataPoints().At(i).SetDoubleValue(m.data.Gauge().DataPoints().At(i).DoubleValue() / aggCount)
			}
		}
		m.updateCapacity()
		m.data.MoveTo(metrics.AppendEmpty())
		m.init()
	}
}

